import { Routes } from '@angular/router';

export const CLIENTE_PERFIL_ROUTES: Routes = [
  {
    path: '',
    children: [
      {
        path: 'change-pass',
        loadComponent: () =>
          import('./change-pass/change-pass.component').then(m => m.ChangePasswordComponent),
      },
      {
        path: 'datos-personales',
        loadComponent: () =>
          import('./datos-personales/datos-personales.component').then(m => m.DatosPersonalesComponent),
      },
      {
        path: 'datos-fiscales',
        loadComponent: () =>
          import('./datos-fiscales/datos-fiscales.component').then(m => m.DatosFiscalesComponent),
      },
      {
        path: 'datos-negocio',
        loadComponent: () =>
          import('./datos-negocio/datos-negocio.component').then(m => m.DatosNegocioComponent),
      },
      {
        path: '',
        redirectTo: 'change-pass',
        pathMatch: 'full',
      },
    ],
  },
];
